        Sole: v.solePct,
        Hybrid: v.hybridPct,
        Consortium: v.consortiumPct,
        Other: v.specialistPct,
      }));
    }
    return vintage.map((v) => ({
      vintage: v.vintage,
      Sole: v.soleHyperscalerKm,
      Hybrid: v.hybridCpKm,
      Consortium: v.carrierConsortiumKm,
      Other: v.specialistKm,
