    route: ROUTE_META[r.route].short,
    routeId: r.route,
    label: ROUTE_META[r.route].label,
    Sole: r.soleHyperscalerPct,
    Hybrid: r.hybridCpPct,
    Consortium: r.carrierConsortiumPct,
    Other: r.specialistPct,
    newKm000: r.newKm000,
